import {summaryMarkup,editProposalInput,collectEditedProposal,summaryNeedsRefresh} from './proposal-summary.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const PROPOSAL_FIELDS=['name','purpose','region','preset','seed','asOf','townOverrides','settings','operations','episodes','summary','assumptions','limitations'];
export function proposalInput(proposal){return Object.fromEntries(PROPOSAL_FIELDS.filter(k=>proposal[k]!==undefined).map(k=>[k,k==='episodes'?proposal[k].map(({id,scenario,...ep})=>ep):proposal[k]]));}
export function applyAgentProposal(draft,p){if(draft.status!=='draft')throw Error('Create a new simulation to apply a new setup.');return {...draft,...proposalInput(p),townRef:p.townRef,townId:p.townId,townName:p.townName,homes:p.homes,opsSettings:p.opsSettings,episodes:p.episodes,scenarioId:'custom',scenarioTitle:p.name,agentProposal:p,step:3};}
export function inflictInput(p){return Object.fromEntries(['name','summary','episodes','assumptions','limitations'].filter(k=>p[k]!==undefined).map(k=>[k,p[k]]));}
export function runInput(p){return Object.fromEntries(['townRef','settings','episodes','asOf','startDate','name','region','purpose'].map(k=>[k,p[k]]));}
export function currentRunInput(m,startDate){return {townRef:m.townRef,settings:m.settings||{},episodes:m.episodes,asOf:m.asOf||'2026-03-31',startDate:startDate||m.asOf||'2026-03-31'};}
export const BASELINE_TOPICS=['Place & service area','Utility & scale','Meters & reads','Team & workflow','Billing & cash','Starting pressures','What-if & recovery'];
export function supportsVoice(host=globalThis){return !!(host.SpeechRecognition||host.webkitSpeechRecognition);}
export function installSetupAgent({root,api,getDraft,onSave,onApply,onBack,mode='setup',fetchImpl=globalThis.fetch.bind(globalThis)}){
 const inflict=mode==='inflict';
 const opening=inflict?'What would you like to change in this simulation? Tell me the tweak, when it starts, and roughly how long it should last.':'Let’s build your starting situation first. Which country and state or province are you in, and what city or service area should we use as context?';
 const state=structuredClone(getDraft().agent||{messages:[],proposal:null,input:'',readAloud:false});
 let available=null,busy=false,applying=false,error=state.pending?'The previous reply was interrupted. Retry your last message.':'',alive=true,recognition=null,listening=false,partial='',voiceBase='';
 const controller=new AbortController();
 const save=()=>{if(alive)onSave(structuredClone(state));};
 function fail(e){if(e.name==='AbortError'||!alive)return;error=e.message||'The assistant could not finish. Please try again.';render();}
 async function request(path,body){const r=await fetchImpl(api+'/setup-agent/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:controller.signal});let data;try{data=await r.json();}catch{throw Error('The setup assistant is unavailable. Your manual setup is still available.');}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'The setup request could not be accepted. Please shorten your message and try again.');return data;}
 function stopVoice(){recognition?.stop();}
 function speak(text){if(!state.readAloud||!globalThis.speechSynthesis)return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-CA';speechSynthesis.speak(utterance);}
 function voice(){if(listening){stopVoice();return;}const Speech=globalThis.SpeechRecognition||globalThis.webkitSpeechRecognition;if(!Speech)return;globalThis.speechSynthesis?.cancel();const current=recognition=new Speech();recognition.lang=navigator.language||'en-CA';recognition.continuous=true;recognition.interimResults=true;voiceBase=state.input||'';partial='';
  recognition.onstart=()=>{if(recognition!==current)return;listening=true;render();};
  recognition.onresult=e=>{if(recognition!==current)return;const heard=Array.from(e.results,r=>r[0].transcript).join(' ');partial=heard;state.input=(voiceBase+' '+heard).trim();const input=root.querySelector('#agent-input');if(input)input.value=state.input;};
  recognition.onerror=e=>{if(recognition!==current)return;error=e.error==='not-allowed'?'Microphone access was declined. You can type your answer instead.':e.error==='no-speech'?'No speech was detected. Try again or type your answer.':'Voice input stopped. You can keep typing.';listening=false;render();};
  recognition.onend=()=>{if(recognition!==current)return;recognition=null;listening=false;if(partial)state.input=(voiceBase+' '+partial).trim();try{save();}catch(e){error=e.message;}render();};
  try{recognition.start();}catch{error='Voice input could not start. You can type instead.';render();}
 }
 async function send(retry=false){if(busy||applying||!available)return;stopVoice();const text=state.input.trim();if(!retry&&!text)return;if(!retry){if(state.messages.length>=48){error='This conversation has reached its limit. Start a new conversation below.';render();return;}state.messages.push({role:'user',content:text});state.input='';state.proposal=null;}busy=true;state.pending=true;error='';
  try{save();render();const context=inflict?structuredClone(runInput(getDraft())):proposalInput(getDraft());const data=await request('chat',{schemaVersion:'setup-agent/1.0',mode,messages:state.messages,...(inflict?{currentRun:context}:{draft:context})});if(!alive)return;state.messages.push({role:'assistant',content:data.message});state.proposal=data.proposal||null;state.summaryDirty=false;state.proposalContext=inflict&&data.proposal?context:null;state.pending=false;save();speak(data.message);}catch(e){if(e.name!=='AbortError')error=e.message;}finally{busy=false;if(alive){state.pending=false;try{save();}catch(e){error=e.message;}render();root.querySelector('#agent-input')?.focus();}}
 }
 async function apply(){if(!state.proposal||applying||state.summaryDirty)return;applying=true;error='';try{stopVoice();render();const context=inflict?structuredClone(runInput(getDraft())):null;if(inflict&&JSON.stringify(context)!==JSON.stringify(state.proposalContext))throw Error('The simulation changed after this proposal. Send a new message to review tweaks against its latest settings.');const result=await request(inflict?'inflict/validate':'validate',inflict?{currentRun:context,proposal:inflictInput(state.proposal)}:proposalInput(state.proposal));if(inflict&&JSON.stringify(context)!==JSON.stringify(runInput(getDraft())))throw Error('The simulation changed while checking. Send a new message before inflicting.');if(alive)await onApply(result.proposal);}catch(e){fail(e);}finally{applying=false;if(alive)render();}}
 async function recheck(){if(applying||busy)return;let candidate;try{candidate=collectEditedProposal(state.proposal,root);}catch(e){error=e.message;root.querySelector('.agent-error').textContent=error;return;}state.proposal=candidate;applying=true;error='';render();try{const context=inflict?structuredClone(runInput(getDraft())):null;if(inflict&&JSON.stringify(context)!==JSON.stringify(state.proposalContext))throw Error('The simulation changed. Send a new message to review its latest settings.');const result=await request(inflict?'inflict/validate':'validate',inflict?{currentRun:context,proposal:inflictInput(candidate)}:proposalInput(candidate));if(!alive)return;state.proposal=result.proposal;state.summaryDirty=false;save();}catch(e){error=e.message;}finally{applying=false;if(alive)render();}}
 function proposalMarkup(p){if(!p)return '';const pairs=Object.entries(p.settings||{}).flatMap(([g,fields])=>Object.entries(fields).map(([key,value])=>`${g}.${key}: ${JSON.stringify(value)}`));return `<section class="agent-proposal"><span class="agent-kicker">${inflict?'PROPOSED TWEAK · VALIDATED':'PROPOSED SETUP · VALIDATED'}</span><h2>${esc(p.name)}</h2><p>${esc(p.summary)}</p><dl>${inflict?`<div><dt>Add to current Year</dt><dd>${p.episodes.length} new period${p.episodes.length===1?'':'s'}</dd></div><div><dt>Analyse through</dt><dd>${esc(p.runTo)}</dd></div>`:`<div><dt>Town</dt><dd>${esc(p.townName)} · ${Number(p.homes).toLocaleString()} homes</dd></div><div><dt>Region context</dt><dd>${esc(p.region||'Not specified')}</dd></div><div><dt>Open Year at</dt><dd>${esc(p.asOf)}</dd></div>`}</dl>${p.episodes.length?`<h3>How the year unfolds</h3><ol>${p.episodes.map(ep=>`<li><strong>${esc(ep.title)}</strong><span>${esc(ep.from)} → ${esc(ep.to||'2026-12-31')}</span></li>`).join('')}</ol>`:'<p>Baseline operations throughout the year.</p>'}${p.assumptions?.length?`<h3>${p.summary.startsWith('Updated configuration')?'Conversation assumptions (edited inputs take precedence)':'Assumptions'}</h3><ul>${p.assumptions.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}<details><summary>Model limits</summary><ul>${p.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>${summaryMarkup(p,{disabled:busy||applying,dirty:state.summaryDirty})}<details><summary>${inflict?'Inspect exact episode settings':`Inspect configuration changes (${p.changes.length})`}</summary><ul>${(p.changes||[]).map(c=>`<li><code>${esc(c.path)}</code><br>${esc(JSON.stringify(c.before))} → ${esc(JSON.stringify(c.after))}</li>`).join('')}</ul>${pairs.length?`<p>Base run settings</p><pre>${esc(pairs.join('\n'))}</pre>`:''}${p.episodes.map(ep=>`<p>${esc(ep.title)}</p><pre>${esc(JSON.stringify(ep.settings,null,2))}</pre>`).join('')}</details><button id="agent-apply" class="primary" type="button" ${busy||applying||state.summaryDirty?'disabled':''}>${applying?'Checking configuration…':inflict?'Inflict & run to period end →':'Use this setup →'}</button><p class="field-note">${inflict?'Adds the reviewed periods and recalculates Year. Existing episodes and base settings are kept.':'This fills in your draft. You’ll review it before opening Year.'}</p></section>`;}
 function render(){if(!alive)return;if(summaryNeedsRefresh(state.proposal))state.summaryDirty=true;root.innerHTML=`<div class="agent-heading"><div><span class="agent-kicker">CLAUDE · ${inflict?'SCENARIO GUIDE':'SETUP GUIDE'}</span><h1>${inflict?'Talk through a tweak.':'Let’s build your baseline.'}</h1></div><button type="button" id="agent-back" class="text-button">${inflict?'Back to Year':'Back to manual setup'}</button></div><p class="intro">${inflict?'Describe a change in your own words. We’ll check its timing and impact before adding it to this Year.':'We’ll ask a few questions at a time about where you are and how things work today, then shape the experiment.'}</p>${inflict?`<p class="field-note">Suggested start: <strong>${esc(getDraft().startDate)}</strong> · ${(getDraft().episodes||[]).length} existing periods kept. You can ask for another start date.</p>`:''}${inflict?'':`<ul class="agent-topics" aria-label="Baseline interview topics">${BASELINE_TOPICS.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}${available===false?`<div class="help-card"><strong>The setup guide isn’t connected yet.</strong><p>${inflict?'You can still pick scenarios from the Year library.':'You can use the starter setups while the assistant is being connected.'}</p></div>`:''}<div class="agent-transcript" role="log" aria-label="Setup conversation" aria-live="polite"><article class="agent-bubble assistant"><span>SETUP GUIDE</span><p>${esc(opening)}</p></article>${state.messages.map(m=>`<article class="agent-bubble ${m.role}"><span>${m.role==='user'?'YOU':'SETUP GUIDE'}</span><p>${esc(m.content)}</p></article>`).join('')}${busy?'<p class="agent-thinking" role="status">Checking the model’s knobs and dials…</p>':''}</div><p class="agent-error" role="alert">${esc(error)}</p>${error&&state.messages.at(-1)?.role==='user'?'<button id="agent-retry" class="text-button" type="button">Retry last message</button>':''}${proposalMarkup(state.proposal)}<form id="agent-form"><label for="agent-input">${listening?'Listening… speak, then stop to review your words.':'Your answer'}</label><textarea id="agent-input" rows="3" maxlength="4000" placeholder="We’re in Ontario, and our billing team is struggling to keep up…" ${busy||applying?'disabled':''}>${esc(state.input)}</textarea><div class="agent-compose-actions"><button class="secondary ${listening?'is-listening':''}" type="button" id="agent-voice" ${!supportsVoice()||busy||applying?'disabled':''}>${listening?'■ Stop listening':'● Speak'}</button><button class="primary" type="submit" ${!available||busy||applying||listening?'disabled':''}>${busy?'Thinking…':'Send →'}</button></div><p class="field-note">${supportsVoice()?'Voice uses your browser’s speech service. Review the transcript before sending.':'Voice isn’t available in this browser. Typing works the same way.'} Sent messages and ${inflict?'the current Year configuration':'your draft configuration'} go to Anthropic.</p>${globalThis.speechSynthesis?`<label class="agent-read"><input type="checkbox" id="agent-read" ${state.readAloud?'checked':''}> Read replies aloud</label>`:''}</form><button class="text-button" id="agent-reset" type="button" ${busy||applying?'disabled':''}>Start a new conversation</button>`;
  root.querySelector('#agent-back').onclick=()=>{try{save();onBack();}catch(e){fail(e);}};root.querySelector('#agent-form').onsubmit=e=>{e.preventDefault();send();};root.querySelector('#agent-input').oninput=e=>{state.input=e.target.value;try{save();}catch(err){error=err.message;root.querySelector('.agent-error').textContent=error;}};
  root.querySelector('#agent-voice').onclick=voice;const read=root.querySelector('#agent-read');if(read)read.onchange=()=>{state.readAloud=read.checked;if(!read.checked)globalThis.speechSynthesis?.cancel();save();};
  root.querySelectorAll('[data-summary-change]').forEach(input=>input.oninput=()=>{state.summaryDirty=true;try{state.proposal=editProposalInput(state.proposal,Number(input.dataset.summaryChange),input.value);save();}catch{}root.querySelector('.summary-status').textContent='Edits need checking. Recheck to update the summary before applying.';root.querySelector('[data-summary-recheck]').hidden=false;root.querySelector('#agent-apply').disabled=true;});const check=root.querySelector('[data-summary-recheck]');if(check)check.onclick=recheck;const button=root.querySelector('#agent-apply');if(button)button.onclick=apply;const retry=root.querySelector('#agent-retry');if(retry)retry.onclick=()=>send(true);
  root.querySelector('#agent-reset').onclick=()=>{stopVoice();state.messages=[];state.proposal=null;state.proposalContext=null;state.summaryDirty=false;state.input='';state.pending=false;error='';try{save();render();}catch(e){fail(e);}};
 }
 render();request('status').then(data=>{if(alive){available=data.available;render();}}).catch(e=>{available=false;fail(e);});
 return ()=>{alive=false;controller.abort();if(recognition){recognition.onend=null;recognition.onresult=null;recognition.onerror=null;recognition.onstart=null;recognition.abort();}globalThis.speechSynthesis?.cancel();};
}
